perl -e '
use strict; use warnings;
my $ROOT = "/bench/repo";
open my $gm, "<", "$ROOT/go.mod" or die;
my $module = "";
while (<$gm>) { if (/^module\s+(\S+)/) { $module = $1; last; } }
close $gm;

my @decls;
my %symbols;
sub parse_file {
    my ($path, $is_internal) = @_;
    open my $f, "<", $path or return;
    local $/; my $content = <$f>; close $f;
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    my $rel_dir = $path; $rel_dir =~ s/^\Q$ROOT\E\/?//; $rel_dir =~ s/\/[^\/]+$//;
    my $import_path = $module . ($rel_dir ? "/$rel_dir" : "");

    while ($content =~ /^func\s+(?:(\w+)\s+\*?(\w+)\)\s+)?(\w+)\s*\(/mg) {
        my ($recv_var, $recv_type, $name) = ($1, $2, $3);
        next unless $is_internal;
        my $key = "$import_path\t" . ($recv_type // "") . "\t$name";
        my %d = (import_path=>$import_path, recv_type=>$recv_type, name=>$name, file=>$path, pkg=>$pkg, rel_dir=>$rel_dir);
        push @decls, \%d;
        $symbols{$key} = \%d;
    }
}

# collect declarations from internal non-test
for my $path (glob("$ROOT/internal/*/*.go"), glob("$ROOT/internal/*/*/*.go"), glob("$ROOT/internal/*/*/*/*.go")) {
    next if $path =~ /_test\.go$/;
    parse_file($path, 1);
}
# also top-level internal files
for my $path (glob("$ROOT/internal/*.go")) {
    next if $path =~ /_test\.go$/;
    parse_file($path, 1);
}

print "Module: $module\n";
print "Declarations: " . scalar(@decls) . "\n";

sub get_imports {
    my ($content) = @_;
    my %imports;
    if ($content =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias //= (split /\//, $path)[-1];
            $imports{$alias} = $path;
        }
    }
    while ($content =~ /import\s+(?:(\w+)\s+)?"([^"]+)"/g) {
        my ($alias, $path) = ($1, $2);
        $alias //= (split /\//, $path)[-1];
        $imports{$alias} = $path;
    }
    return %imports;
}

my %call_counts;
my %caller_files;

my @all_go;
sub find_go { my $dir = shift; opendir my $dh, $dir or return; while (my $e = readdir $dh) {
    next if $e =~ /^\./;
    my $p = "$dir/$e";
    if (-d $p) { find_go($p) } elsif ($p =~ /\.go$/) { push @all_go, $p }
} closedir $dh; }
find_go($ROOT);

my @skip = qw(if for switch return make new len cap append delete copy panic print println close complex real imag func go defer);

for my $fpath (@all_go) {
    open my $f, "<", $fpath or next;
    local $/; my $content = <$f>; close $f;
    my ($file_pkg) = $content =~ /^package\s+(\w+)/m;
    my %imports = get_imports($content);
    my $rel_dir = $fpath; $rel_dir =~ s/^\Q$ROOT\E\/?//; $rel_dir =~ s/\/[^\/]+$//;
    my $file_import = $module . ($rel_dir ? "/$rel_dir" : "");

    # qualified calls alias.Func(
    while ($content =~ /(\w+)\.(\w+)\s*\(/g) {
        my ($alias, $name) = ($1, $2);
        next unless exists $imports{$alias};
        my $imp = $imports{$alias};
        my $key = "$imp\t\t$name";
        if (exists $symbols{$key}) {
            $call_counts{$key}++; $caller_files{$key}{$fpath} = 1;
        }
    }

    # method calls .Method(
    while ($content =~ /\.(\w+)\s*\(/g) {
        my $name = $1;
        for my $key (keys %symbols) {
            my ($imp, $recv, $sym) = split /\t/, $key;
            next unless $sym eq $name && $recv ne "";
            if ($file_import eq $imp || grep { $_ eq $imp } values %imports) {
                $call_counts{$key}++; $caller_files{$key}{$fpath} = 1;
            }
        }
    }

    # bare calls
    while ($content =~ /(?<![\w.])(\w+)\s*\(/g) {
        my $name = $1;
        next if grep { $_ eq $name } @skip;
        for my $key (keys %symbols) {
            my ($imp, $recv, $sym) = split /\t/, $key;
            next unless $sym eq $name && $recv eq "" && $file_import eq $imp;
            $call_counts{$key}++; $caller_files{$key}{$fpath} = 1;
        }
    }
}

my @ranked = sort { $call_counts{$b} <=> $call_counts{$a} } keys %call_counts;
print "\nTop 25:\n";
for my $i (0..24) {
    last unless $i <= $#ranked;
    my $key = $ranked[$i];
    my $d = $symbols{$key};
    my $sym = ($d->{recv_type} ? "($d->{recv_type})." : "") . $d->{name};
    my $file = $d->{file}; $file =~ s/^\Q$ROOT\E\///;
    printf "  %4d  %s  %s\n", $call_counts{$key}, $sym, $file;
}
if (@ranked) {
    my $key = $ranked[0]; my $d = $symbols{$key};
    my $sym = ($d->{recv_type} ? "($d->{recv_type})." : "") . $d->{name};
    print "\nWINNER: $sym — $d->{file} — ~$call_counts{$key}\n";
}
'

