use strict; use warnings;
my $ROOT = "/bench/repo";
open my $gm, "<", "$ROOT/go.mod" or die;
my $module = ""; while (<$gm>) { if (/^module\s+(\S+)/) { $module = $1; last; } }
close $gm;

# Collect declarations
my @decls;
for my $path (glob("$ROOT/internal/*/*.go"), glob("$ROOT/internal/*/*/*.go"), glob("$ROOT/internal/*/*/*/*.go"), glob("$ROOT/internal/*.go")) {
    next if $path =~ /_test\.go$/;
    open my $f, "<", $path or next;
    my @lines = <$f>; close $f;
    my ($pkg) = $lines[0] =~ /package\s+(\w+)/ ? ($lines[0] =~ /package\s+(\w+)/)[0] : "";
    for (@lines) { /package\s+(\w+)/ and $pkg=$1; }
    my $rel_dir = $path; $rel_dir =~ s/^\Q$ROOT\E\/?//; $rel_dir =~ s/\/[^\/]+$//;
    my $import_path = $module . ($rel_dir ? "/$rel_dir" : "");
    my $line_no = 0;
    for my $line (@lines) {
        $line_no++;
        if ($line =~ /^func\s+(?:(\w+)\s+\*?(\w+)\)\s+)?(\w+)\s*\(/) {
            my ($rv, $rt, $name) = ($1, $2, $3);
            push @decls, {name=>$name, recv=>$rt, import=>$import_path, file=>$path, rel=>$rel_dir, pkg=>$pkg};
        }
    }
}

# Read all go file contents (stripped comments)
my @all_go;
sub find_go { my $dir=shift; opendir my $dh,$dir or return; while(my $e=readdir $dh){
  next if $e=~/^\./; my $p="$dir/$e"; if(-d $p){find_go($p)} elsif($p=~/\.go$/){push @all_go,$p}
} closedir $dh; } find_go($ROOT);

sub strip { my $c=shift; $c=~s/\/\*.*?\*\///gs; my @l=split/\n/,$c; @l=map{s/\/\/.*$//;$_}@l; join"\n",@l }

my %imports_cache;
sub get_imports {
    my ($raw)=@_; return %{$imports_cache{$raw}} if exists $imports_cache{$raw};
    my %imports;
    while ($raw =~ /import\s*\((.*?)\)/gs) {
        while ($1 =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($a,$p)=($1,$2); $a//=(split/\//,$p)[-1]; $imports{$a}=$p;
        }
    }
    while ($raw =~ /^import\s+(?:(\w+)\s+)?"([^"]+)"/mg) {
        my ($a,$p)=($1,$2); $a//=(split/\//,$p)[-1]; $imports{$a}=$p;
    }
    $imports_cache{$raw}=\%imports; return %imports;
}

my @skip = qw(if for switch return make new len cap append delete copy panic print println close complex real imag func go defer map struct interface chan select range default case break continue const var type import package goto fallthrough);

my %counts;
for my $d (@decls) {
    my $name = $d->{name}; my $recv = $d->{recv}; my $imp = $d->{import};
    my $count = 0;
    for my $fpath (@all_go) {
        open my $f,"<",$fpath or next; local $/; my $raw=<$f>; close $f;
        my $content = strip($raw);
        my %imports = get_imports($raw);
        my $rel_dir = $fpath; $rel_dir =~ s/^\Q$ROOT\E\/?//; $rel_dir =~ s/\/[^\/]+$//;
        my $file_import = $module . ($rel_dir ? "/$rel_dir" : "");

        if (!$recv) {
            # package-level function
            if ($file_import eq $imp) {
                my $re = qr/(?<![\w.])\Q$name\E\s*\(/;
                while ($content =~ /$re/g) { $count++ }
            }
            # qualified cross-package
            for my $alias (keys %imports) {
                next unless $imports{$alias} eq $imp;
                my $re = qr/\Q$alias\E\.\Q$name\E\s*\(/;
                while ($content =~ /$re/g) { $count++ }
            }
        } else {
            # method: count .MethodName( in same package OR files importing package
            my $in_pkg = ($file_import eq $imp);
            my $imports_pkg = grep { $_ eq $imp } values %imports;
            next unless $in_pkg || $imports_pkg;
            my $re = qr/\.\Q$name\E\s*\(/;
            while ($content =~ /$re/g) { $count++ }
        }
    }
    $counts{"$d->{name}\t$d->{file}\t".($d->{recv}//"")} = $count;
}

my @sorted = sort { $counts{$b} <=> $counts{$a} } keys %counts;
print "Top 20:\n";
for my $i (0..19) {
    my ($name,$file,$recv) = split /\t/, $sorted[$i];
    my $sym = $recv ? "($recv).$name" : $name;
    $file =~ s/^\Q$ROOT\E\///;
    printf "%4d  %s  %s\n", $counts{$sorted[$i]}, $sym, $file;
}
'

