use strict; use warnings;
my $ROOT = "/bench/repo";
open my $gm, "<", "$ROOT/go.mod" or die;
my $module = ""; while (<$gm>) { if (/^module\s+(\S+)/) { $module = $1; last; } }
close $gm;

my @decls;
for my $path (glob("$ROOT/internal/*/*.go"), glob("$ROOT/internal/*/*/*.go"), glob("$ROOT/internal/*/*/*/*.go"), glob("$ROOT/internal/*.go")) {
    next if $path =~ /_test\.go$/;
    open my $f, "<", $path or next;
    my @lines = <$f>; close $f;
    my $rel = $path; $rel =~ s/^\Q$ROOT\E\///;
    my $dir = $rel; $dir =~ s/\/[^\/]+$//;
    my $import = $module . "/" . $dir;
    for my $line (@lines) {
        if ($line =~ /^func\s+(?:\((\w+)\s+\*?(\w+)\)\s+)?(\w+)\s*\(/) {
            push @decls, {name=>$3, recv=>$2, file=>$rel, import=>$import};
        }
    }
}
print "declarations: " . scalar(@decls) . "\n";

my @files;
sub walk { my $d=shift; opendir my $dh,$d or return; while(my $e=readdir $dh){
  next if $e=~/^\./; my $p="$d/$e"; if(-d $p){walk($p)} elsif($p=~/\.go$/){push @files,$p}
} closedir $dh; } walk($ROOT);

sub strip { my $c=shift; $c=~s/\/\*.*?\*\///gs; my @l=split/\n/,$c; @l=map{s/\/\/.*$//;$_}@l; join"\n",@l }
sub imports_of {
    my ($raw)=@_; my %imp;
    while ($raw =~ /import\s*\((.*?)\)/gs) {
        my $b=$1; while ($b =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($a,$p)=($1,$2); $a//=(split/\//,$p)[-1]; $imp{$a}=$p;
        }
    }
    while ($raw =~ /^import\s+(?:(\w+)\s+)?"([^"]+)"/mg) {
        my ($a,$p)=($1,$2); $a//=(split/\//,$p)[-1]; $imp{$a}=$p;
    }
    return %imp;
}

my %results;
for my $d (@decls) {
    my $count=0;
    for my $fpath (@files) {
        open my $f,"<",$fpath or next; local $/; my $raw=<$f>; close $f;
        my $c = strip($raw);
        my %imp = imports_of($raw);
        my $rel = $fpath; $rel =~ s/^\Q$ROOT\E\/?//; my $dir=$rel; $dir=~s/\/[^\/]+$//;
        my $fimp = $module . ($dir ? "/$dir" : "");

        if (!$d->{recv}) {
            if ($fimp eq $d->{import}) {
                $count += () = ($c =~ /(?<![\w.])\Q$d->{name}\E\s*\(/g);
            }
            for my $alias (keys %imp) {
                next unless $imp{$alias} eq $d->{import};
                $count += () = ($c =~ /\Q$alias\E\.\Q$d->{name}\E\s*\(/g);
            }
        } else {
            next unless ($fimp eq $d->{import}) || grep { $_ eq $d->{import} } values %imp;
            $count += () = ($c =~ /\.\Q$d->{name}\E\s*\(/g);
        }
    }
    $results{"$d->{name}|$d->{file}|".($d->{recv}//"")} = $count;
}

my @sorted = sort { $results{$b} <=> $results{$a} } keys %results;
print "Top 25:\n";
for my $i (0..24) {
    my ($name,$file,$recv) = split /\|/, $sorted[$i];
    my $sym = $recv ? "($recv).$name" : $name;
    printf "%4d  %s  %s\n", $results{$sorted[$i]}, $sym, $file;
}
my ($name,$file,$recv) = split /\|/, $sorted[0];
my $sym = $recv ? "($recv).$name" : $name;
print "\nWinner: $sym — $file — ~$results{$sorted[0]}\n";
'

